DISACCORDO = 15.0      # gradi: oltre, una soluzione è una variante
MARGINE = 10.0         # gradi di λ☉ fuori finestra ancora considerati ("bordo")
DERIVA_MAX = 5.0       # gradi di λ☉ oltre la finestra misurata in cui la deriva viene ancora applicata

def _rel(x, ref):   return (x - ref + 180) % 360 - 180
def _med(v, w=None):
    """mediana, pesata con il numero di meteore N di ogni soluzione quando dato"""
    if not v: return None
    w = [1] * len(v) if w is None else [max(1, x) for x in w]
    pairs = sorted(zip(v, w)); half = sum(w) / 2; acc = 0
    for x, wt in pairs:
        acc += wt
        if acc >= half: return x
def _sep(ra1, de1, ra2, de2):
    a1, d1, a2, d2 = map(math.radians, (ra1, de1, ra2, de2))
    c = math.sin(d1) * math.sin(d2) + math.cos(d1) * math.cos(d2) * math.cos(a1 - a2)
    return math.degrees(math.acos(max(-1, min(1, c))))

def _consensus(sols):
    """Raggruppa le soluzioni concordi: vince il gruppo con PIÙ soluzioni d'accordo (a parità,
    più meteore). Le altre diventano varianti. Restituisce (concordi, discordanti)."""
    if len(sols) <= 1: return sols, []
    def close(s, t):
        dra = s[8] if s[8] is not None else (t[8] if t[8] is not None else 1.0)
        dde = s[9] if s[9] is not None else (t[9] if t[9] is not None else 0.0)
        dl = _rel(t[5], s[5])
        return abs(dl) <= 2 * DISACCORDO and _sep((s[6] + dra * dl) % 360, s[7] + dde * dl, t[6], t[7]) <= DISACCORDO
    best = max(sols, key=lambda s: (sum(close(s, t) for t in sols), sum(t[11] for t in sols if close(s, t))))
    good = [t for t in sols if close(best, t)]
    bad = [t for t in sols if t not in good]
    return good, bad

def _entry(code, name, sols, variant=None):
    p0 = sols[0][5]; W = [s[11] for s in sols]
    pk = (p0 + _med([_rel(s[5], p0) for s in sols], W)) % 360
    dra = _med([s[8] for s in sols if s[8] is not None], [s[11] for s in sols if s[8] is not None])
    dde = _med([s[9] for s in sols if s[9] is not None], [s[11] for s in sols if s[9] is not None])
    known = dra is not None and dde is not None
    dra = 1.0 if dra is None else dra; dde = 0.0 if dde is None else dde
    rr = [((s[6] + dra * _rel(pk, s[5])) % 360, s[7] + dde * _rel(pk, s[5])) for s in sols]
    ra = (rr[0][0] + _med([_rel(r[0], rr[0][0]) for r in rr], W)) % 360; de = _med([r[1] for r in rr], W)
    wins = [(_rel(s[3], pk), _rel(s[4], pk)) for s in sols if s[3] is not None and s[4] is not None]
    est = not wins
    a, b = ((-10, 10) if est else (min(w[0] for w in wins), max(w[1] for w in wins)))
    vg = _med([s[10] for s in sols if s[10] is not None])
    nm = name if variant is None else f"{name} [variante {variant} λ{pk:.0f}]"
    return {'code': code, 'name': nm, 'start': (pk + a) % 360, 'end': (pk + b) % 360, 'window_est': est,
            'peak': pk, 'ra': ra, 'dec': de, 'v': vg, 'zhr': '?', 'n': max(s[11] for s in sols),
            'n_sol': len(sols), 'parent': next((s[12] for s in sols if s[12]), ''),
            'rad_lon': _ecl_lon(ra, de), 'drift': (dra, dde), 'drift_known': known,
            'daytime': name.lower().startswith('daytime'), 'variant': variant is not None,
            'solutions': sols}

SHOWERS = []
_groups = {}
for s in IAU_ALL:
    if s[5] is None or s[6] is None or s[7] is None: continue
    _groups.setdefault(s[0], []).append(s)
for code, sols in _groups.items():
    names = [s[1] for s in sols]; name = max(set(names), key=names.count)
    good, bad = _consensus(sols)
    e = _entry(code, name, good); e['discordanti'] = len(bad); SHOWERS.append(e)
    for s in bad:
        SHOWERS.append({**_entry(code, name, [s], variant=s[2][:7]), 'discordanti': 0})

# Antielio: attivo 10 dic → 20 set, radiante mobile (punto antisolare)
ANTIHELION = {'name': 'Antielio (ANT, ex Piscidi)', 'start': _date_to_lam_j2000('10 Dec'),
              'end': _date_to_lam_j2000('20 Sep'), 'v': 30, 'zhr': '4', 'parent': 'vari'}

def _in(lam, s, e):
    return (s <= lam <= e) if e >= s else (lam >= s or lam <= e)

def _d(a, b):
    return abs((a - b + 180) % 360 - 180)

def _dl_clamped(sh, lam):
    """distanza dal picco in λ☉, limitata alla finestra misurata ± DERIVA_MAX; True se limitata"""
    dl = (lam - sh['peak'] + 180) % 360 - 180
    a = _rel(sh['start'], sh['peak']) - DERIVA_MAX; b = _rel(sh['end'], sh['peak']) + DERIVA_MAX
    c = max(a, min(b, dl)); return c, c != dl

def _radec_at(sh, lam):
    dl, lim = _dl_clamped(sh, lam); dra, ddec = sh['drift']
    return (sh['ra'] + dra * dl) % 360, sh['dec'] + ddec * dl, lim

def _outside(lam, s, e):
    """0 se dentro la finestra; altrimenti gradi fuori (+ dopo la fine, − prima dell'inizio)"""
    if _in(lam, s, e): return 0.0
    after = (lam - e) % 360; before = (s - lam) % 360
    return after if after <= before else -before

def active_showers(sun_lon_of_date, year_frac, margin=MARGINE):
    """Sciami attivi per λ☉ ALLA DATA (anche fino a 'margin'° fuori finestra: campo 'bordo')."""
    p = precession_to_date(year_frac)
    lam = (sun_lon_of_date - p) % 360            # λ☉ in J2000 per il confronto col catalogo
    out = []
    for s in SHOWERS:
        o = _outside(lam, s['start'], s['end'])
        if abs(o) <= margin:
            dp = _d(lam, s['peak']); ra, de, lim = _radec_at(s, lam)
            out.append({**s, 'peak_date_lon': (s['peak'] + p) % 360,
                        'rad_lon_date': (s['rad_lon'] + p) % 360,          # nodo: radiante al picco (come finora)
                        'rad_lon_date_deriva': (_ecl_lon(ra, de) + p) % 360,  # nodo con il radiante alla data
                        'dist_peak': dp, 'bordo': o, 'deriva_estrapolata': lim})
    if _in(lam, ANTIHELION['start'], ANTIHELION['end']):
        ant_lon = (sun_lon_of_date + 180) % 360
        out.append({**ANTIHELION, 'peak': None, 'peak_date_lon': None, 'rad_lon_date': ant_lon,
                    'ra': None, 'dec': None, 'dist_peak': None})
    out.sort(key=lambda x: 999 if x['dist_peak'] is None else x['dist_peak'])
    return out

def radiant_radec(name, sun_lon_of_date=None, year_frac=2026.7):
    """AR/Dec (gradi) del radiante ALLA DATA, con la deriva giornaliera; Antielio: punto antisolare."""
    for s in SHOWERS:
        if s['name'] == name:
            if sun_lon_of_date is None:
                return s['ra'], s['dec']
            lam = (sun_lon_of_date - precession_to_date(year_frac)) % 360
            ra, de, _ = _radec_at(s, lam)            # deriva solo entro la finestra misurata ±5°
            return ra, de
    if name.startswith('Antielio') and sun_lon_of_date is not None:
        lon = math.radians((sun_lon_of_date + 180) % 360); e = math.radians(OBLIQ_J2000)
        ra = math.degrees(math.atan2(math.sin(lon) * math.cos(e), math.cos(lon))) % 360
        dec = math.degrees(math.asin(math.sin(lon) * math.sin(e)))
        return ra, dec
    return None


def tag(sh):
    """etichetta di vigilanza per i report: bordo, variante, disaccordo, deriva"""
    t = []
    if sh.get('bordo'): t.append(f"fuori finestra {sh['bordo']:+.0f}°")
    if sh.get('variant'): t.append("soluzione separata: picco o radiante diversi dal consenso")
    if sh.get('discordanti'): t.append(f"{sh['discordanti']} soluz. discordanti separate")
    if sh.get('deriva_estrapolata'): t.append("radiante fermo al bordo della finestra misurata")
    if sh.get('window_est'): t.append("finestra stimata")
    return ('  (' + '; '.join(t) + ')') if t else ''

def solutions_near(ra, dec, sun_lon_of_date, year_frac, radius=15.0, margin=30.0):
    """Ricerca libera in TUTTE le soluzioni: radianti entro 'radius'° da (AR, Dec) alla data,
    con λ☉ entro 'margin'° dalla finestra (o dal picco se manca). Per il metodo 'prima i dati'."""
    lam = (sun_lon_of_date - precession_to_date(year_frac)) % 360
    out = []
    for s in IAU_ALL:
        if s[5] is None or s[6] is None or s[7] is None: continue
        a, b = (s[3], s[4]) if (s[3] is not None and s[4] is not None) else ((s[5] - 10) % 360, (s[5] + 10) % 360)
        o = _outside(lam, a, b)
        if abs(o) > margin: continue
        dl = max(-DERIVA_MAX, min(DERIVA_MAX, (lam - s[5] + 180) % 360 - 180))
        r = (s[6] + (s[8] if s[8] is not None else 1.0) * dl) % 360
        d = s[7] + (s[9] if s[9] is not None else 0.0) * dl
        sep = _sep(r, d, ra, dec)
        if sep <= radius:
            out.append({'code': s[0], 'name': s[1], 'soluzione': s[2], 'ra': r, 'dec': d, 'sep': sep,
                        'fuori_finestra': o, 'dist_peak': _d(lam, s[5]), 'v': s[10], 'n': s[11]})
    return sorted(out, key=lambda x: x['sep'])
